package com.mandu.liquiddialer
import androidx.compose.ui.semantics.getOrNull
import androidx.compose.ui.test.*
import androidx.datastore.preferences.core.edit
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class AlphabeticalSettingsToolsUiTest:OrganizedSettingsFixture(){
 @Before fun reset(){runBlocking{ctx.ldStore.edit{it[K.alphabeticalSettingsTools]=false;it[K.compactSettingsTools]=false;it[K.settingsToolSearch]=false}};await{LdApp.settings.value.let{!it.alphabeticalSettingsTools&&!it.compactSettingsTools&&!it.settingsToolSearch}}}
 private fun enable(){runBlocking{ctx.ldStore.edit{it[K.alphabeticalSettingsTools]=true}};await{LdApp.settings.value.alphabeticalSettingsTools};settle()}
 private fun checkOrder(section:String,az:Boolean){val expected=settingsSectionTools(section,az).map{"settings_tool_"+it.route};val actual=rule.onAllNodes(SemanticsMatcher("tool row"){n->n.config.getOrNull(androidx.compose.ui.semantics.SemanticsProperties.TestTag)?.let{it in expected}==true},true).fetchSemanticsNodes().map{it.config[androidx.compose.ui.semantics.SemanticsProperties.TestTag]};assertEquals(expected,actual)}
 @Test fun defaultOffExactOriginalCatalog(){assertFalse(LdSettings().alphabeticalSettingsTools);for(section in listOf("live","notes","calculators"))assertEquals(ORGANIZED_TOOLS.filter{it.section==section},settingsSectionTools(section,false));assertTrue(settingsSectionTools("unknown",true).isEmpty());start();show("settingstools:notes");rule.onNodeWithTag("settings_tools_az_label",true).assertDoesNotExist();checkOrder("notes",false)}
 @Test fun alphabeticalEverySectionSameMembershipNoCatalogMutation(){val before=ORGANIZED_TOOLS.toList();for(section in listOf("live","notes","calculators")){val old=settingsSectionTools(section,false);val az=settingsSectionTools(section,true);assertEquals(old.toSet(),az.toSet());assertEquals(old.size,az.size);assertEquals(az.map{it.title.lowercase(java.util.Locale.ROOT)}.sorted(),az.map{it.title.lowercase(java.util.Locale.ROOT)})};assertEquals(before,ORGANIZED_TOOLS);assertEquals(37,ORGANIZED_TOOLS.size)}
 @Test fun displayedOrderAndDescriptionsAllSections(){start();enable();for(section in listOf("live","notes","calculators")){show("settingstools:"+section);rule.onNodeWithTag("settings_tools_az_label",true).assertExists();checkOrder(section,true);for(t in settingsSectionTools(section,true))rule.onNodeWithText(t.detail,false,true).assertExists()}}
 @Test fun allThirtySevenRoutesUnchangedNoSideEffects(){start();enable();val before=LdApp.settings.value;for(t in ORGANIZED_TOOLS){show("settingstools:"+t.section);tapTag("settings_tool_"+t.route);assertEquals(t.route,opened.last())};assertEquals(before,LdApp.settings.value);assertNull(rule.activity.state.pendingCall)}
 @Test fun switchReversibleOnePreference(){start();show("settingshub:tools");val before=LdApp.settings.value;tapTag("alphabetical_settings_tools_switch");await{LdApp.settings.value.alphabeticalSettingsTools};assertEquals(before.copy(alphabeticalSettingsTools=true),LdApp.settings.value);show("settingstools:live");checkOrder("live",true);show("settingshub:tools");tapTag("alphabetical_settings_tools_switch");await{!LdApp.settings.value.alphabeticalSettingsTools};assertEquals(before,LdApp.settings.value);show("settingstools:live");checkOrder("live",false);rule.onNodeWithTag("settings_tools_az_label",true).assertDoesNotExist()}
 @Test fun compactIndependentSearchOrderUnchanged(){start();val search=searchSettingsTools("calculator");enable();runBlocking{ctx.ldStore.edit{it[K.compactSettingsTools]=true;it[K.settingsToolSearch]=true}};await{LdApp.settings.value.compactSettingsTools&&LdApp.settings.value.settingsToolSearch};show("settingstools:calculators");checkOrder("calculators",true);for(t in settingsSectionTools("calculators",true))rule.onNodeWithText(t.detail,false,true).assertDoesNotExist();assertEquals(search,searchSettingsTools("calculator"));show("settingshub:tools");rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_tool_query")),true).performTextReplacement("IVR");settle();rule.onNodeWithText(ORGANIZED_TOOLS.first{it.route=="ivrmenus"}.detail,false,true).assertExists()}
 @Test fun finderAndClassicAndIndividualControlsRemain(){assertTrue(SettingsFinder.search("A-Z order").any{it.id=="alphabetical-settings-tools"&&it.route=="settingshub:tools"});start();enable();show("settingshub:classic");text(SETTINGS_GROUPS.first().summary).assertExists();show("settings:recents");text("Home pe favourite contacts dikhao/chhupao").assertExists()}
 @Test fun dayAndOffPixels(){start();enable();show("settingstools:notes");shot("SET510-day-notes");show("settingstools:calculators");shot("SET510-day-calculators");show("settingshub:tools");tapTag("alphabetical_settings_tools_switch");await{!LdApp.settings.value.alphabeticalSettingsTools};rule.mainClock.autoAdvance=true;rule.onNodeWithTag("alphabetical_settings_tools_switch",true).performScrollTo();settle();shot("SET510-off");show("settingstools:notes");shot("SET510-off-notes")}
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w320dp-h640dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class AlphabeticalSettingsToolsNightUiTest:OrganizedSettingsFixture(){
 @Test fun nightLargeAlphabeticalWithAndWithoutCompact(){start(night=true);runBlocking{ctx.ldStore.edit{it[K.alphabeticalSettingsTools]=true;it[K.compactSettingsTools]=false}};await{LdApp.settings.value.alphabeticalSettingsTools&&!LdApp.settings.value.compactSettingsTools};show("settingstools:live");shot("SET510-night-live");runBlocking{ctx.ldStore.edit{it[K.compactSettingsTools]=true}};await{LdApp.settings.value.compactSettingsTools};show("settingstools:calculators");shot("SET510-night-compact");rule.onNodeWithTag("settings_tools_az_label",true).assertIsDisplayed();assertNull(rule.activity.state.pendingCall)}
}
